// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address[] memory _tos, uint[] memory v) public {
        // Only test when caller is not the authorized address
        address caller = address(0x1234);
        vm.assume(caller != 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        // Bound array lengths to be equal and non-empty for valid input
        vm.assume(_tos.length > 0 && _tos.length == v.length);
        // Bound each v[i] to prevent overflow (though not strictly needed)
        for (uint i = 0; i < v.length; i++) {
            v[i] = bound(v[i], 0, type(uint256).max / 1e18);
        }
        // Attempt the call from the unauthorized caller
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeCall(c.transfer, (_tos, v)));
        // The rule: the call MUST revert (success == false)
        assertTrue(!success, "transfer should revert for unauthorized caller");
    }
}

